$('#emailprograms').onclick=()=>{let box=$('#emailsessions');box.innerHTML=state.sessions.map(s=>'<label style="display:flex;align-items:center;gap:10px;margin:10px 0"><input class="email-session" type="checkbox" value="'+s.id+'" style="width:auto"><span><b>'+prog(s).name+'</b> — '+s.label+'</span></label>').join('')||'<div class="empty">No sessions available.</div>';$('#emailresult').textContent='';$('#emaildialog').showModal()};async function emailRecipients(){let ids=$('.email-session:checked').map(x=>x.value);if(!ids.length)throw Error('Select at least one session.');return api('/api/communications/recipients',{method:'POST',body:JSON.stringify({session_ids:ids})})}$('#copyemails').onclick=async()=>{try{let j=await emailRecipients();await navigator.clipboard.writeText(j.emails.join(', '));$('#emailresult').textContent=j.count+' unique email'+(j.count===1?'':'s')+' copied.'}catch(e){$('#emailresult').textContent=e.message}};$('#openmail').onclick=async()=>{try{let j=await emailRecipients(),subject=encodeURIComponent($('#emailsubject').value),body=encodeURIComponent($('#emailbody').value);location.href='mailto:?bcc='+encodeURIComponent(j.emails.join(','))+'&subject='+subject+'&body='+body;$('#emailresult').textContent='Opening your email app with '+j.count+' recipient'+(j.count===1?'':'s')+' in BCC.'}catch(e){$('#emailresult').textContent=e.message}};
$('#newabsence').onclick=()=>{$('#absenceparticipant').innerHTML=state.participants.map(p=>'<option value="'+p.id+'">'+p.name+'</option>').join('');$('#absencedialog').showModal()};$('#absenceform').onsubmit=async e=>{e.preventDefault();await api('/api/absences',{method:'POST',body:JSON.stringify({participant_id:$('#absenceparticipant').value,date:$('#absencedate').value,reason:$('#absencereason').value})});$('#absencedialog').close();e.target.reset();await load()};
$('#newstaff').onclick=()=>$('#staffdialog').showModal();$('#staffform').onsubmit=async e=>{e.preventDefault();await api('/api/staff',{method:'POST',body:JSON.stringify({name:$('#staffname').value,email:$('#staffemail').value,role:$('#staffrole').value})});$('#staffdialog').close();e.target.reset();await load()};
$('#exportcsv').onclick=()=>location.href='/api/export/roster.csv';$('#openhosted').onclick=()=>window.open('/register/'+encodeURIComponent(state.organization.slug||'demo'),'_blank');$('#copyembed').onclick=async()=>{await navigator.clipboard.writeText($('#embedcode').value);$('#copyembed').textContent='Copied';setTimeout(()=>$('#copyembed').textContent='Copy embed code',1500)};
$('#connectstripe').onclick=async()=>{let j=await api('/api/billing/connect/start',{method:'POST'});$('#paymentstatus').textContent=j.message;await load()};boot();